mapper.select:
        select  t.address,t.city_code,t.city_code cityCode,t.name,t.tel,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId,t.ext_community_id,t.ext_community_id extCommunityId 
from s_community t 
where 1 =1 

   and t.address= #{address}


   and t.city_code= #{cityCode}


   and t.name= #{name}


   and t.tel= #{tel}


   and t.status_cd= #{statusCd}


   and t.community_id= #{communityId}


   and t.ext_community_id= #{extCommunityId}

order by t.create_time desc

   limit #{page}, #{row}

mapper.update:
